best_attempt.sparql:
SELECT DISTINCT ?film ?filmLabel ?director ?directorLabel ?birthPlace ?birthPlaceLabel WHERE {
  # find films whose label mentions "preston tylk"
  ?film a dbo:Film ;
        rdfs:label ?filmLabel .
  FILTER(CONTAINS(LCASE(STR(?filmLabel)), "preston tylk"))

  # director may be given with dbo:director or dbp:director
  OPTIONAL { ?film dbo:director ?director . }
  OPTIONAL { ?film dbp:director ?director . }

  # director birth place may be given with dbo:birthPlace or dbp:birthPlace
  OPTIONAL { ?director dbo:birthPlace ?birthPlace . }
  OPTIONAL { ?director dbp:birthPlace ?birthPlace . }

  # optional labels for readability
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER(langMatches(lang(?directorLabel), "en")) }
  OPTIONAL { ?birthPlace rdfs:label ?birthPlaceLabel . FILTER(langMatches(lang(?birthPlaceLabel), "en")) }
  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER(langMatches(lang(?filmLabel), "en")) }
}
LIMIT 50

